<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin Dashboard</title><link rel="stylesheet" href="../style.css"></head><body><header><strong>Admin Dashboard</strong><nav><a href="dashboard.php">Orders</a><a href="menu.php">Manage Menu</a><a href="logout.php">Logout</a></nav></header><main class="wrap"><section class="hero"><h1>Welcome, <?=e($_SESSION['admin_username'] ?? 'Admin')?>!</h1><p>View incoming orders and update their status.</p></section><h2>Customer Orders</h2><div class="panel" style="overflow-x:auto"><?php if($orders->num_rows===0):?><p>No orders yet. Place a test order from the customer menu.</p><?php else:?><table><thead><tr><th>Order</th><th>Customer</th><th>Table</th><th>Total</th><th>Status</th><th>Date</th><th>Action</th></tr></thead><tbody><?php while($o=$orders->fetch_assoc()):?><tr><td>#<?=e($o['id'])?></td><td><?=e($o['customer_name'])?></td><td><?=e($o['table_number'])?></td><td>₹<?=number_format((float)$o['total'],2)?></td><td><?=e($o['status'])?></td><td><?=e($o['created_at'])?></td><td><form class="actions" method="post" action="update_order.php"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=e($o['id'])?>"><select name="status"><?php foreach(['Pending','Preparing','Ready','Completed','Cancelled'] as $s):?><option <?=$o['status']===$s?'selected':''?>><?=e($s)?></option><?php endforeach;?></select><button type="submit">Update</button><a class="btn secondary" href="order.php?id=<?=e($o['id'])?>">Details</a></form></td></tr><?php endwhile;?></tbody></table><?php endif;?></div></main></body></html>